insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, auto_check)
select x.id, v.ci, v.ex, v.dn::jsonb, v.ac::jsonb
from (values
(1, 1, 'الكيمياء العضوية هي فرع الكيمياء الذي يدرس المركبات التي تحتوي على الكربون.', '["الكيمياء التحليلية تُعنى بتحديد مكونات المادة وأنواعها وكمياتها.","","الكيمياء الذرية تُعنى بتركيب الذرة: النظائر والتركيب الإلكتروني والروابط ونظريات تركيب المادة.","الكيمياء الفيزيائية تدرس سلوك المواد وتفاعلاتها وخصائصها والطاقة المصاحبة لها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.144Z"}'::jsonb),
(2, 1, 'تحلل مواد التغليف في البيئة من موضوعات الكيمياء البيئية التي تدرس أثر المواد في البيئة.', '["الكيمياء الحيوية تدرس المواد والعمليات والتفاعلات داخل المخلوقات الحية.","","صحيح أن كثيرًا من مواد التغليف عضوية، لكن دراسة تحللها في البيئة من اختصاص الكيمياء البيئية.","الكيمياء الفيزيائية تدرس سلوك المواد وتفاعلاتها وخصائصها والطاقة المصاحبة لها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.144Z"}'::jsonb),
