(7, 0, 'مركبات الكلوروفلوروكربون (CFCs) تتفكك في الستراتوسفير وتطلق الكلور الذي يحطم جزيئات الأوزون.', '["","الأكسجين يكوّن الأوزون ولا يستنزفه.","الأشعة فوق البنفسجية جزء من دورة تكوّن الأوزون الطبيعية، وليست سبب تناقصه.","ثاني أكسيد الكربون من غازات الاحتباس الحراري، ولا يحطم الأوزون."]'::jsonb, '{"passed":false,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":false,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.145Z"}'::jsonb),
(8, 0, 'اسمه يدل على مكوناته: كلور (Cl) وفلور (F) وكربون (C).', '["","Ca رمز الكالسيوم لا الكربون.","O رمز الأكسجين، ولا يدخل في تركيبه.","Cr رمز الكروم لا الكربون."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.145Z"}'::jsonb),
(9, 2, 'كل جزيء أوزون $\text{O}_3$ فيه 3 ذرات، فعدد الجزيئات $= 18 \div 3 = 6$.', '["هذا ناتج القسمة على 9.","هذا ناتج القسمة على 6.","","هذا عدد جزيئات $\\text{O}_2$ ($18 \\div 2$)، لا الأوزون."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.145Z"}'::jsonb),
(10, 1, 'الكلوروفلوروكربون يستنزف طبقة الأوزون الحامية من الأشعة فوق البنفسجية، ويبقى في الجو مدة طويلة.', '["النيتروجين نحو 78% من الهواء، وهو غاز خامل نسبيًا وغير ضار.","","أول أكسيد الكربون سام عند استنشاقه، لكنه لا يستنزف طبقة الأوزون.","ثاني أكسيد الكربون يسهم في الاحتباس الحراري، لكنه لا يحطم طبقة الأوزون."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.145Z"}'::jsonb)
