(1, 1, 'الكتلة مقياس لكمية المادة في الجسم، ولا تتغير بتغير المكان.', '["الحجم مقدار الحيز الذي يشغله الجسم، لا كمية المادة فيه.","","الكثافة نسبة الكتلة إلى الحجم، لا كمية المادة.","الوزن قوة جذب الجاذبية للكتلة، فيتغير بتغير المكان."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.145Z"}'::jsonb),
