(2, 0, 'بعد ملاحظة الظاهرة يصوغ العالم فرضية، أي تفسيرًا مبدئيًا قابلًا للاختبار.', '["","الاستنتاج يأتي في آخر الطريقة بعد التجربة وتحليل البيانات.","تحليل النتائج يأتي بعد إجراء التجربة.","اختبار الفرضية بالتجربة يأتي بعد صياغتها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.145Z"}'::jsonb),
(3, 0, 'الفرضية تُختبر بالتجريب؛ فالتجربة هي التي تؤيد الفرضية أو تنفيها.', '["","الملاحظة تسبق صياغة الفرضية، ولا تثبتها.","التحليل يتم على بيانات التجربة، فلا يغني عنها.","الاستنتاج يُبنى على نتائج التجربة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.145Z"}'::jsonb),
