(5, 0, 'درجة الحرارة هي العامل الذي يغيّره المجرب، فهي العامل المستقل. وسرعة الذوبان هي العامل التابع.', '["","العامل التابع هو سرعة الذوبان التي تتغير تبعًا لدرجة الحرارة.","التجربة هي الإجراء كله، لا أحد عوامله.","العامل الضابط يُثبَّت للمقارنة، ودرجة الحرارة هنا متغيرة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.145Z"}'::jsonb),
(6, 1, 'المجرب يغيّر درجة الحرارة بنفسه، فهي العامل المستقل. وذوبان الملح هو العامل التابع.', '["العامل التابع هو مقدار الذوبان الذي يُقاس.","","العامل الضابط يبقى ثابتًا، ودرجة الحرارة هنا تتغير.","درجة الحرارة تتغير في التجربة، فلا تكون ثابتة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.145Z"}'::jsonb),
