from (values
(1, 3, 'توصيل الكهرباء يُقاس دون أن يتغير تركيب النحاس، فهو خاصية فيزيائية.', '["تكوّن الصدأ تفاعل الحديد مع الأكسجين والرطوبة، فهو كيميائي.","الاحتراق تفاعل مع الأكسجين ينتج مواد جديدة.","فقد الفضة بريقها ناتج عن تفاعلها مع مركبات الكبريت في الهواء، فهو كيميائي.",""]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.148Z"}'::jsonb),
(2, 3, 'اللون يُلاحظ دون أن يتغير تركيب المادة، فهو خاصية فيزيائية.', '["الصدأ مادة جديدة تتكون بالتفاعل، فهي خاصية كيميائية.","اشتعال الصوديوم تفاعل عنيف مع الماء، فهو خاصية كيميائية.","التأكسد تفاعل مع الأكسجين، فهو خاصية كيميائية.",""]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.148Z"}'::jsonb),
(3, 2, 'الرائحة تُدرك دون أن يتغير تركيب العطر، فهي خاصية فيزيائية. والسؤال عن وصف الرائحة لا عن عملية البخ.', '["الرش والتبخر تغير فيزيائي فعلًا، لكن الجملة تصف رائحة العطر، وهي خاصية.","لم تتكون مادة جديدة.","","الخاصية الكيميائية تظهر بالتفاعل، والرائحة لا تحتاج إلى تفاعل."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.148Z"}'::jsonb),
(4, 3, 'الخاصية المميزة لا تعتمد على كمية المادة، فتميّز المادة عن غيرها. والكثافة كذلك: لكل مادة نقية كثافة ثابتة.', '["الكتلة تتغير بتغير كمية المادة، فهي غير مميزة.","الطول يعتمد على حجم العينة، فهو غير مميز.","الحجم يتغير بتغير كمية المادة، فهو غير مميز.",""]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.148Z"}'::jsonb),
(5, 1, 'الكتلة تعتمد على كمية المادة، فلا تميّز مادة عن أخرى؛ هي خاصية فيزيائية غير مميزة.', '["الكتلة تُقاس بالأرقام، فهي كمية لا نوعية.","","الخاصية المميزة لا تعتمد على كمية المادة، والكتلة تعتمد عليها.","قياس الكتلة لا يغيّر تركيب المادة، فهي فيزيائية."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.148Z"}'::jsonb),
(6, 0, 'قابلية الحديد للصدأ في الهواء تظهر بتفاعله وتكوين مادة جديدة (أكسيد الحديد)، فهي خاصية كيميائية.', '["","الغليان تغير في الحالة دون مادة جديدة، فهو فيزيائي.","الانصهار تغير في الحالة، فهو فيزيائي.","الذوبان لا يكوّن مادة جديدة، فهو فيزيائي."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.148Z"}'::jsonb),
(7, 2, 'تحلل السكر يكوّن مواد جديدة (كربون وماء)، فهو خاصية كيميائية.', '["اللون وصف فيزيائي.","الحالة والشكل البلوري خواص فيزيائية.","","اللون خاصية فيزيائية."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.148Z"}'::jsonb),
(8, 3, 'التأكسد (أو عدمه) يتعلق بقدرة المادة على التفاعل، فهو خاصية كيميائية. والبقية خواص فيزيائية.', '["اللون واللمعان خاصيتان فيزيائيتان.","قابلية التشكل خاصية فيزيائية.","درجة الانصهار خاصية فيزيائية.",""]'::jsonb, '{"passed":false,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":false,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.148Z"}'::jsonb),
(9, 3, 'تحلل السكر بالتسخين يكوّن مواد جديدة، فهو خاصية كيميائية لا فيزيائية.', '["الحالة والشكل البلوري خواص فيزيائية.","اللون خاصية فيزيائية.","الطعم خاصية فيزيائية.",""]'::jsonb, '{"passed":false,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":false,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.148Z"}'::jsonb),
(10, 1, 'تكوّن مركب جديد (كربونات النحاس) يعني تفاعلًا كيميائيًا، فهي خاصية كيميائية.', '["تكونت مادة جديدة، فليست خاصية فيزيائية.","","الخاصية الكمية تُقاس بالأرقام، وهذا وصف لتفاعل.","ليست من تصنيفات خواص المادة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.148Z"}'::jsonb),
(11, 1, 'ذوبان الجليد تحوّل من الصلب إلى السائل دون تكوين مادة جديدة، فهو فيزيائي.', '["الحموضة تتعلق بتفاعل المادة، فهي خاصية كيميائية.","","الاتحاد بمادة أخرى تفاعل كيميائي.","عدم الاتحاد يصف قابلية التفاعل، فهو خاصية كيميائية أيضًا."]'::jsonb, '{"passed":false,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":false,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.148Z"}'::jsonb),
(12, 0, 'تغير لون الفضة (اسودادها) ناتج عن تفاعلها مع مركبات الكبريت وتكوين كبريتيد الفضة، فهو كيميائي.', '["","الغليان تغير في الحالة فقط.","التسامي تحول من صلب إلى غاز دون مادة جديدة.","ذوبان الجليد تغير في الحالة فقط."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.148Z"}'::jsonb),
(13, 0, 'التغير الفيزيائي يغيّر بعض الخواص الفيزيائية (كالشكل والحالة) دون تكوين مواد جديدة.', '["","الخاصية صفة للمادة، والسؤال عن تغير.","التغير الكيميائي ينتج عنه مادة جديدة.","الخاصية الكيميائية صفة لا تغير، وتظهر عند تكوين مواد جديدة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.148Z"}'::jsonb),
(14, 0, 'الاحتراق يحوّل البنزين إلى ثاني أكسيد الكربون وماء، أي مواد جديدة، فهو تغير كيميائي.', '["","تكونت مواد جديدة، فليس فيزيائيًا.","قابلية البنزين للاشتعال خاصية كيميائية، أما احتراقه الفعلي فتغير كيميائي.","الاحتراق تغير لا خاصية، وليس فيزيائيًا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.148Z"}'::jsonb),
(15, 3, 'ذوبان الجليد تحوّل الماء من الصلب إلى السائل دون تكوين مادة جديدة، فهو تغير فيزيائي.', '["الذوبان عملية تحدث، فهو تغير لا خاصية.","لا تفاعل في الذوبان.","لم تتكون مادة جديدة؛ ما زال ماءً.",""]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.148Z"}'::jsonb),
(16, 0, 'الاحتراق تفاعل مع الأكسجين ينتج مواد جديدة، فهو تغير كيميائي.', '["","تتكون مواد جديدة، فليس فيزيائيًا.","قابلية الاشتعال هي الخاصية، أما الاحتراق نفسه فتغير.","الاحتراق تغير، وليس فيزيائيًا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.148Z"}'::jsonb),
