from (values
(1, 2, 'الإلكترونات جسيمات سالبة الشحنة تتحرك في الفراغ المحيط بالنواة.', '["البروتونات موجبة وتوجد داخل النواة.","النيوترونات متعادلة وتوجد داخل النواة.","","الفوتونات حزم من الطاقة الضوئية لا شحنة لها، وليست من مكونات الذرة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.152Z"}'::jsonb),
(2, 1, 'النواة تضم البروتونات والنيوترونات، وكتلتهما معًا تكاد تساوي كتلة الذرة كلها؛ لأن كتلة الإلكترون صغيرة جدًا.', '["الفراغ المحيط بالنواة تشغله الإلكترونات، وكتلتها ضئيلة.","","البروتونات جزء من كتلة النواة فقط، ومعها النيوترونات.","النيوترونات جزء من كتلة النواة فقط، ومعها البروتونات."]'::jsonb, '{"passed":false,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":false,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.152Z"}'::jsonb),
(3, 1, 'أثبتت تجربة رذرفورد أن معظم حجم الذرة فراغ؛ لأن أغلب جسيمات ألفا نفذت من صفيحة الذهب دون انحراف.', '["النواة صغيرة جدًا مقارنة بحجم الذرة، وإن كانت تحمل معظم كتلتها.","","النيوترون جسيم داخل النواة الصغيرة.","الإلكترون جسيم صغير جدًا، والفراغ الذي يتحرك فيه هو الذي يشغل الحجم."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.152Z"}'::jsonb),
(4, 0, 'النواة موجبة لاحتوائها على البروتونات، وتحمل أغلب كتلة الذرة.', '["","النواة موجبة لا سالبة، وتحمل أغلب الكتلة لا نصفها.","الشحنة صحيحة، لكن النواة تحمل أغلب الكتلة لا نصفها.","النواة موجبة، والكتلة خارجها (الإلكترونات) ضئيلة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.152Z"}'::jsonb),
(5, 1, 'اكتشف طومسون الإلكترون بتجارب أنبوب الأشعة المهبطية، وحسب نسبة شحنته إلى كتلته.', '["رذرفورد اكتشف النواة بتجربة صفيحة الذهب.","","أينشتاين عُرف بالنظرية النسبية وتفسير التأثير الكهروضوئي.","بويل عُرف بقانون الغازات (الضغط والحجم)."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.152Z"}'::jsonb),
(6, 0, 'كتلة الذرة تكاد تساوي كتلة نواتها (البروتونات والنيوترونات).', '["","الفراغ يشغل الحجم لا الكتلة.","النيوترونات جزء من كتلة النواة، والبروتونات جزؤها الآخر.","كتلة الإلكترون نحو 1/1840 من كتلة البروتون."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.152Z"}'::jsonb),
(7, 0, 'العبارة الخاطئة «لا وجود للفراغ»: معظم حجم الذرة فراغ كما أثبتت تجربة رذرفورد.', '["","عبارة صحيحة من فروض دالتون.","عبارة صحيحة: الذرة أصغر جزء من العنصر يحمل خواصه.","عبارة صحيحة: لكل عنصر ذرات مميزة بعدد بروتوناتها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.152Z"}'::jsonb),
(8, 0, 'قذف رذرفورد صفيحة رقيقة من الذهب بجسيمات ألفا الموجبة، فكشف ارتدادُ بعضها وجودَ النواة.', '["","أشعة جاما لا شحنة لها ولا كتلة، فلا ترتد عن النواة كما في التجربة.","جسيمات بيتا إلكترونات خفيفة، ولم تُستعمل في التجربة.","الأشعة السينية موجات كهرومغناطيسية، ولم تُستعمل في التجربة."]'::jsonb, '{"passed":false,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":false,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.152Z"}'::jsonb),
(9, 2, 'شحنة البروتون (+1) تعادل شحنة الإلكترون (−1)، فإذا تساوى عددهما كانت الشحنة الكلية صفرًا.', '["النيوترونات متعادلة فلا يؤثر عددها في الشحنة.","النيوترونات متعادلة فلا يؤثر عددها في الشحنة.","","في النواة بروتونات موجبة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.152Z"}'::jsonb),
(10, 0, 'الشحنة الكلية = شحنة البروتونات (+) + شحنة الإلكترونات (−)، وعددهما متساوٍ فالمجموع صفر.', '["","مجموع شحنة الإلكترونات سالب لا صفر.","مثلا شحنة الإلكترونات سالب أيضًا لا صفر.","مجموع شحنة البروتونات موجب لا صفر."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.152Z"}'::jsonb),
(11, 0, 'أشعة المهبط تنحرف نحو اللوح الموجب، فهي سالبة، وهي سيل من الإلكترونات.', '["","لو كانت موجبة لانحرفت نحو اللوح السالب.","المتعادلة لا تنحرف في المجال، وأشعة المهبط تنحرف.","تنحرف في المجالين الكهربائي والمغناطيسي، فلها شحنة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.152Z"}'::jsonb),
(12, 2, 'الذرة أصغر جزء من العنصر يحتفظ بخواصه.', '["الإلكترون واحد في كل العناصر، فلا يحمل خواص عنصر بعينه.","البروتون واحد في كل العناصر.","","النيوترون واحد في كل العناصر."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.152Z"}'::jsonb),
(13, 3, 'ارتداد قلة من الجسيمات يعني اصطدامها بجزء صغير جدًا كثيف موجب في مركز الذرة، هو النواة.', '["الذرة متعادلة، والموجب هو النواة لا الذرة كلها.","هذا ما دل عليه نفاذ معظم الجسيمات، لا ارتداد بعضها.","الإلكترونات خفيفة جدًا ولا ترد جسيم ألفا.",""]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T04:48:47.152Z"}'::jsonb),
